// The one Back manager of the app shell. A layer that is open (the agent sheet, another sheet, point mode, a pushed screen) asks for one
// history entry with the same URL; the browser's Back closes the topmost layer instead of leaving the page, and closing a layer any
// other way removes its entry, so the history stays as it was. Hosts: the AgentLayer (order `agent`) and, later, sheets and stacks.
import { useEffect, useLayoutEffect, useRef } from 'react';

/** Local Back priority: pointing, artifact view, sheet, assistant/PM, pushed screen, then browser. */
export type BackOrder = 'point' | 'artifact' | 'sheet' | 'agent' | 'stack';
const RANK: Readonly<Record<BackOrder, number>> = { point: 0, artifact: 1, sheet: 2, agent: 3, stack: 4 };

interface Layer { readonly order: BackOrder; readonly close: () => unknown; popped: boolean }

const layers = new Set<Layer>();
/** `popstate` events caused by our own `history.back()`, which must not close anything. */
let ignored = 0;
let listening = false;
/** The layer kind the page was loaded on top of (history state survives a reload), until a layer adopts it. */
let persisted: unknown = typeof window === 'undefined' || !window.history ? undefined : (window.history.state as { appShell?: unknown } | null)?.appShell;
/** Layers that opened while our own `history.back()` was still pending: they push their entry once it has landed (a push in between cancels it). */
const waiting: (() => void)[] = [];

/**
 * Runs `action` once the history entry of a sheet that is closing has really gone. A choice that navigates (the app's router replaces the
 * URL) must not run before: the sheet's own `history.back()` would undo it. Call it in the same handler that closes the sheet.
 */
export function afterBack(action: () => void): void {
  // The sheet's effect cleanup (which starts its `history.back()`) runs after this handler returns.
  setTimeout(() => { if (ignored > 0) waiting.push(action); else action(); }, 0);
}

/**
 * Runs `action` after the open stack layers (a ListDetail's pushed detail) have gone back. A nav choice that replaces the URL must not
 * run before: the stack layer's cleanup `history.back()` would restore the detail's URL over it. The layers are released here, not in
 * their cleanup (which only runs once the choice has hidden the screen, too late), and their cleanup then does nothing.
 */
export function afterStacksBack(action: () => void): void {
  const stacks = [...layers].filter(layer => layer.order === 'stack' && !layer.popped);
  if (!stacks.length) { action(); return; }
  waiting.push(action);
  for (const layer of stacks) { layer.popped = true; layers.delete(layer); ignored += 1; window.history.back(); }
}

const topmost = (): Layer | undefined => [...layers].toSorted((a, b) => RANK[a.order] - RANK[b.order])[0];

function onPopState(): void {
  if (ignored > 0) {
    ignored -= 1;
    if (ignored === 0) for (const start of waiting.splice(0)) start();
    return;
  }
  const top = topmost();
  if (!top) return;
  // The entry is already gone: the layer closes without calling `history.back()` again.
  if (top.popped) return;
  top.popped = true;
  const restore = () => {
    if (!layers.has(top) || !top.popped) return;
    top.popped = false;
    window.history.pushState({ appShell: top.order }, '');
  };
  try { void Promise.resolve(top.close()).then(closed => { if (closed === false) restore(); }, restore); }
  catch { restore(); }
}

/**
 * While `open`, the layer owns one history entry (`history.pushState({ appShell: order }, '')`, same URL). `popstate` closes only the
 * topmost open layer. Any other close (the effect ends because `open` became false or the component unmounted) calls `history.back()`
 * once, and that `popstate` is ignored. `close` may change between renders.
 */
export function useBackLayer(open: boolean, close: () => unknown, order: BackOrder): void {
  const latest = useRef(close);
  useLayoutEffect(() => { latest.current = close; });
  useEffect(() => {
    if (!open) return;
    const layer: Layer = { order, close: () => latest.current(), popped: false };
    let started = false;
    const start = () => {
      started = true;
      // After a reload the page still sits on the entry its layer pushed before: that one layer adopts it instead of stacking a second.
      // An artifact sheet pushes its own: its entry can be stale by then, and closing an adopted one could leave the page.
      const adopt = persisted === order && order !== 'artifact';
      persisted = undefined;
      if (!adopt) window.history.pushState({ appShell: order }, '');
      layers.add(layer);
    };
    if (!listening) { window.addEventListener('popstate', onPopState); listening = true; }
    // A sheet that closes as this layer opens (the account menu choosing « Améliorer l'app ») is still going back: wait for it.
    if (ignored > 0) waiting.push(start); else start();
    return () => {
      const at = waiting.indexOf(start);
      if (at >= 0) waiting.splice(at, 1);
      if (!started) return;
      layers.delete(layer);
      if (!layer.popped) { ignored += 1; window.history.back(); }
    };
  }, [open, order]);
}

'use client';

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import type { PointerEvent, RefObject } from 'react';

export interface DragPosition { readonly left: number; readonly top: number }

/** Pointer-capture drag shared with the agent layer. Controls remain clickable and the whole surface stays reachable. */
export function useDraggable({ box, position, onPositionChange, enabled }: {
  readonly box: RefObject<HTMLElement | null>;
  readonly position: DragPosition | null;
  readonly onPositionChange: (position: DragPosition) => void;
  readonly enabled: boolean;
}) {
  const drag = useRef<{ dx: number; dy: number } | null>(null);
  const [viewport, setViewport] = useState(0);
  useEffect(() => { const resize = () => setViewport(count => count + 1); window.addEventListener('resize', resize); return () => window.removeEventListener('resize', resize); }, []);
  useLayoutEffect(() => {
    const rect = box.current?.getBoundingClientRect();
    if (!position || !enabled || !rect || !rect.width) return;
    const left = Math.min(Math.max(position.left, 0), Math.max(0, window.innerWidth - rect.width)), top = Math.min(Math.max(position.top, 0), Math.max(0, window.innerHeight - rect.height));
    if (left !== position.left || top !== position.top) onPositionChange({ left, top });
  }, [box, position, enabled, viewport, onPositionChange]);
  const onPointerDown = (event: PointerEvent<HTMLElement>) => {
    const rect = box.current?.getBoundingClientRect();
    if (!enabled || !rect || event.button !== 0 || (event.target as HTMLElement).closest('button, a[href]')) return;
    drag.current = { dx: event.clientX - rect.left, dy: event.clientY - rect.top };
    event.currentTarget.setPointerCapture?.(event.pointerId);
  };
  const onPointerMove = (event: PointerEvent<HTMLElement>) => {
    const grab = drag.current, rect = box.current?.getBoundingClientRect();
    if (!grab || !rect) return;
    onPositionChange({ left: Math.min(Math.max(event.clientX - grab.dx, 0), Math.max(0, window.innerWidth - rect.width)), top: Math.min(Math.max(event.clientY - grab.dy, 0), Math.max(0, window.innerHeight - rect.height)) });
  };
  const end = () => { drag.current = null; };
  return { onPointerDown, onPointerMove, onPointerUp: end, onPointerCancel: end };
}

import { clsx } from 'clsx';
import type { ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export { PHONE_BELOW } from './use-media';

export function cn(...inputs: ClassValue[]): string { return twMerge(clsx(inputs)); }

/** Thrown when no automatic copy worked; `text` is what the person must copy by hand (a viewer shows it selected). */
export class ManualCopyError extends Error {
  readonly text: string;
  constructor(text: string) { super('Copy the text by hand'); this.name = 'ManualCopyError'; this.text = text; }
}

/**
 * Copies `text` using the host's callback when given, else the async Clipboard API (secure contexts only), else a hidden
 * textarea and `document.execCommand('copy')` (works over plain HTTP). Throws `ManualCopyError` when none worked.
 * This is the one place this item touches the clipboard; `npm run check` keeps it that way.
 */
export async function copyText(text: string, onCopy?: (text: string) => Promise<void>): Promise<void> {
  if (onCopy) return onCopy(text);
  try { const clipboard = globalThis.navigator?.clipboard; if (clipboard) { await clipboard.writeText(text); return; } }
  catch { /* denied or unfocused: use the selection route */ }
  const doc = globalThis.document;
  if (doc?.body && typeof doc.execCommand === 'function') {
    const area = doc.createElement('textarea');
    area.value = text;
    area.setAttribute('readonly', '');
    area.style.cssText = 'position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;pointer-events:none';
    const focus = doc.activeElement instanceof HTMLElement ? doc.activeElement : undefined;
    doc.body.append(area);
    try { area.select(); area.setSelectionRange(0, text.length); if (doc.execCommand('copy')) return; }
    catch { /* fall through */ }
    finally { area.remove(); focus?.focus({ preventScroll: true }); }
  }
  throw new ManualCopyError(text);
}

/**
 * A block's `labels` or `icons`: `defaults` with each partial override on top, later ones winning. A key an override leaves `undefined`
 * keeps the value below it, so a host can pass `{ title: maybe }` safely.
 */
export function withDefaults<T extends object>(defaults: T, ...overrides: readonly (Partial<T> | undefined)[]): T {
  const merged: Record<string, unknown> = { ...defaults as Record<string, unknown> };
  for (const override of overrides) for (const [key, value] of Object.entries(override ?? {})) if (value !== undefined) merged[key] = value;
  return merged as T;
}

// Where an embedded page puts its own header controls when a host header already exists. The app shell (`app-shell`) provides the
// element of its screen header to the screen on show; `AgentWorkspace layout="embedded"` (`pi-app`) renders its bar's controls there
// (a React portal), so the page has one header row. Null outside a shell screen on show: the page keeps its own bar. Host concern: Pi has
// no layout. It lives here because both items depend on `utils` and neither imports the other.
import { createContext, useContext } from 'react';

export const ScreenHeaderSlotContext = createContext<HTMLElement | null>(null);

/** The host header's slot for the calling screen's controls, or null when there is none. */
export const useScreenHeaderSlot = (): HTMLElement | null => useContext(ScreenHeaderSlotContext);

'use client';

import { useCallback, useEffect, useMemo, useState, useSyncExternalStore } from 'react';
import type { RefObject } from 'react';

/** Phone layout is strictly below 768 CSS pixels, independently of pointer type. */
export const PHONE_BELOW = 768;
export const PHONE_QUERY = `(width < ${PHONE_BELOW}px)`;
const serverMatches = () => false;

export function useMedia(query: string): boolean {
  const media = useMemo(() => globalThis.matchMedia?.(query) ?? globalThis.window?.matchMedia?.(query), [query]);
  const subscribe = useCallback((notify: () => void) => {
    media?.addEventListener('change', notify);
    return () => media?.removeEventListener('change', notify);
  }, [media]);
  const snapshot = useCallback(() => media?.matches === true, [media]);
  return useSyncExternalStore(subscribe, snapshot, serverMatches);
}

export const usePhone = (): boolean => useMedia(PHONE_QUERY);

export interface VisualViewportBox { readonly top: number; readonly height: number }

function useVisualViewportBox(enabled: boolean): VisualViewportBox | null {
  const [box, setBox] = useState<VisualViewportBox | null>(null);
  useEffect(() => {
    const viewport = globalThis.window?.visualViewport ?? globalThis.visualViewport;
    if (!enabled || !viewport) return;
    const read = () => {
      if (viewport.scale > 1.01) return;
      const next = { top: viewport.offsetTop, height: viewport.height };
      setBox(previous => previous && previous.top === next.top && previous.height === next.height ? previous : next);
    };
    read();
    viewport.addEventListener('resize', read);
    viewport.addEventListener('scroll', read);
    return () => { viewport.removeEventListener('resize', read); viewport.removeEventListener('scroll', read); };
  }, [enabled]);
  return enabled ? box : null;
}

/** Null without a visual viewport; pinch zoom keeps the last unzoomed box. */
export const useVisualViewport = (): VisualViewportBox | null => useVisualViewportBox(true);

/** The chat's inset is relative to its own bottom, not necessarily the layout viewport's bottom. */
export function useKeyboardInset(ref: RefObject<HTMLElement | null>, enabled: boolean): void {
  const viewport = useVisualViewportBox(enabled);
  useEffect(() => {
    const element = ref.current;
    if (!enabled || !viewport || !element) return;
    const measure = () => element.style.setProperty('--composer-keyboard-inset', `${Math.max(0, element.getBoundingClientRect().bottom - viewport.height - viewport.top)}px`);
    const observer = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(measure);
    observer?.observe(element);
    measure();
    return () => { observer?.disconnect(); element.style.removeProperty('--composer-keyboard-inset'); };
  }, [ref, enabled, viewport]);
}

export type Persistence = 'session' | 'local';

/** Viewer conveniences only: browser policy can deny the storage object or an individual operation. */
export function storageFor(persist: Persistence = 'session'): Storage | undefined {
  try { return persist === 'local' ? globalThis.localStorage ?? globalThis.window?.localStorage : globalThis.sessionStorage ?? globalThis.window?.sessionStorage; }
  catch { return undefined; }
}

export function readPersisted(key: string, persist: Persistence = 'session'): string | null {
  try { return storageFor(persist)?.getItem(key) ?? null; }
  catch { return null; }
}

export function writePersisted(key: string, value: string | null, persist: Persistence = 'session'): void {
  try {
    const storage = storageFor(persist);
    if (value === null) storage?.removeItem(key);
    else storage?.setItem(key, value);
  } catch { /* persistence is a viewer convenience */ }
}

export function readPersistedJson(key: string, persist: Persistence = 'session'): unknown {
  try { return JSON.parse(readPersisted(key, persist) ?? 'null'); }
  catch { return null; }
}

export function writePersistedJson(key: string, value: unknown, persist: Persistence = 'session'): void {
  try { const text = JSON.stringify(value); if (text !== undefined) writePersisted(key, text, persist); }
  catch { /* malformed convenience data cannot interrupt the viewer */ }
}

export const readFlag = (key: string): boolean => readPersisted(key) === '1';
export const writeFlag = (key: string, on: boolean): void => writePersisted(key, on ? '1' : null);
